const input = $input.first().json || {};
const requestId = input.request_id || input.requestId || '';
const toolInput = input.tool_input || input.toolInput || {};
const metrics = toolInput.metrics || { leads: 0, meetings: 0, wins: 0 };
const report = {
  period: toolInput.period || 'weekly',
  generated_at: new Date().toISOString(),
  kpis: {
    total_leads: Number(metrics.leads || 0),
    meetings_booked: Number(metrics.meetings || 0),
    won_deals: Number(metrics.wins || 0)
  },
  notes: toolInput.notes || 'Rapor otomatik olarak oluşturuldu.'
};
return [{ json: { request_id: requestId, success: true, data: { summary: 'Rapor başarıyla oluşturuldu.', report_json: report }, error: null, usage: { time_ms: 240, tokens: 90, cost: 0.0009 }, artifacts: [{ type: 'text', name: 'report.json', url: '', meta: { report } }] } }];
